import React from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  MdDashboard,
  MdWork,
  MdBuildCircle,
  MdDevices,
  MdHandshake,
  MdChevronLeft,
  MdChevronRight,
} from 'react-icons/md';
import './Sidebar.css';

const navItems = [
  { path: '/dashboard', label: 'Dashboard', icon: <MdDashboard /> },
  { path: '/careers', label: 'Careers', icon: <MdWork /> },
  { path: '/services', label: 'Services', icon: <MdBuildCircle /> },
  { path: '/platforms', label: 'Platforms', icon: <MdDevices /> },
  { path: '/collaborations', label: 'Collaborations', icon: <MdHandshake /> },
];

const Sidebar = ({ isOpen, setIsOpen }) => {
  const location = useLocation();

  return (
    <aside className={`sidebar ${isOpen ? 'open' : 'closed'}`}>
      {/* Logo */}
      <div className="sidebar-logo">
        <div className="logo-icon">A</div>
        {isOpen && <span className="logo-text">AdminPanel</span>}
      </div>

      {/* Toggle button */}
      <button className="sidebar-toggle" onClick={() => setIsOpen(!isOpen)}>
        {isOpen ? <MdChevronLeft /> : <MdChevronRight />}
      </button>

      {/* Navigation */}
      <nav className="sidebar-nav">
        {isOpen && <p className="nav-section-title">MAIN MENU</p>}
        {navItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) =>
              `nav-item ${isActive ? 'active' : ''}`
            }
            title={!isOpen ? item.label : ''}
          >
            <span className="nav-icon">{item.icon}</span>
            {isOpen && <span className="nav-label">{item.label}</span>}
            {isOpen && location.pathname.startsWith(item.path) && (
              <span className="active-indicator"></span>
            )}
          </NavLink>
        ))}
      </nav>

      {/* Footer */}
      {isOpen && (
        <div className="sidebar-footer">
          <p>Company Admin v1.0</p>
        </div>
      )}
    </aside>
  );
};

export default Sidebar;
